            if "headers" in redactedKwargs:
                redactedKwargsHeaders = redactedKwargs["headers"]
                if (
                    "Tapo_tag" in redactedKwargsHeaders
                    and redactedKwargsHeaders["Tapo_tag"] != ""
                ):
