                if (
                    "Host" in redactedKwargsHeaders
                    and redactedKwargsHeaders["Host"] != ""
                ):
                    redactedKwargsHeaders["Host"] = "REDACTED"
                if (
                    "Referer" in redactedKwargsHeaders
                    and redactedKwargsHeaders["Referer"] != ""
                ):
