class DiscoverReply:
    def __init__(self, payload):
        self.payload = payload

    def json(self):
        if isinstance(self.payload, Exception):
            raise self.payload
        return self.payload


@pytest.mark.parametrize(
    "payload,offered",
    [
        ({"error_code": 0, "result": {"tpap": {"pake": [2], "tls": 1}}}, True),
        ({"error_code": 0, "result": {"tpap": {"pake": [0]}}}, False),
